export function getSupportingArticle(slug: string) { return supportingArticles.find((article) => article.slug === slug); }

export function getSupportingArticlesByCategory() {
  return blogCategories
    .map((category) => ({
      category,
      items: supportingArticles.filter((article) => article.category === category),
    }))
    .filter((group) => group.items.length > 0);
}
